-- Link all occurrences generated by a recurring booking to one series.
alter table public.appointments
  add column if not exists recurrence_series_id uuid;

create index if not exists appointments_recurrence_series_idx
  on public.appointments (barbershop_id, recurrence_series_id, date_hour)
  where recurrence_series_id is not null;

comment on column public.appointments.recurrence_series_id is
  'Shared identifier for appointments created together as one recurring booking series.';
